import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { installSpaceApp } from "../handlers/installSpaceApp";
import type { ApiError } from "../runtime/client";
import type { SpaceAppType } from "../types/SpaceAppType";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof installSpaceApp>>;
type Vars = { spaceId: SpacePartition; appType: SpaceAppType };

export function useInstallSpaceApp(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => installSpaceApp(vars.spaceId, vars.appType),
    ...options,
  });
}
